package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	input := scanner.Text()

	fmt.Print(doAppearInSomeCell(input))
}

func doAppearInSomeCell(input string) string {
	if len(input) < 3 {
		return "No"
	}

	valid := map[string]bool{
		"ABC": true, "ACB": true, "BAC": true,
		"BCA": true, "CAB": true, "CBA": true,
	}

	for i := 0; i <= len(input)-3; i++ {
		substr := input[i : i+3]
		if valid[substr] {
			return "Yes"
		}
	}

	return "No"
}

